alter table public.trade_chains add column circle_id uuid references public.circles(id) on delete cascade;
alter table public.trade_chains add column title text not null default 'Reciprocal trade chain';
alter table public.trade_chains add column description text not null default '';
alter table public.trade_chains add column version integer not null default 1;
alter table public.trade_chains add column execution_mode text not null default 'sequential' check(execution_mode in('simultaneous','sequential','conditional'));
alter table public.trade_chains add column updated_at timestamptz not null default now();
alter table public.trade_chain_links add column position integer not null default 0;
alter table public.trade_chain_links add column due_at timestamptz;
alter table public.trade_chain_links add column conditions text not null default '';
alter table public.trade_chain_links add column evidence_note text;

create table public.trade_chain_acceptances(chain_id uuid not null references public.trade_chains(id) on delete cascade,profile_id uuid not null references public.profiles(id),version integer not null,accepted_at timestamptz not null default now(),primary key(chain_id,profile_id));
create table public.trade_chain_messages(id uuid primary key default gen_random_uuid(),chain_id uuid not null references public.trade_chains(id) on delete cascade,author_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 1500),created_at timestamptz not null default now());
create table public.trade_chain_history(id bigint generated always as identity primary key,chain_id uuid not null references public.trade_chains(id) on delete cascade,actor_id uuid references public.profiles(id),event text not null,note text not null default '',snapshot jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.trade_chain_holds(id uuid primary key default gen_random_uuid(),chain_id uuid not null references public.trade_chains(id) on delete cascade,link_id uuid references public.trade_chain_links(id) on delete cascade,created_by uuid not null references public.profiles(id),kind public.hold_kind not null,detail text not null,action_owner_id uuid references public.profiles(id),review_at timestamptz,resolved_at timestamptz,created_at timestamptz not null default now());
alter table public.trade_chain_acceptances enable row level security;alter table public.trade_chain_messages enable row level security;alter table public.trade_chain_history enable row level security;alter table public.trade_chain_holds enable row level security;
grant select on public.trade_chain_acceptances,public.trade_chain_messages,public.trade_chain_history,public.trade_chain_holds to authenticated;

create or replace function public.is_chain_participant(target_chain_id uuid,target_profile_id uuid default auth.uid())returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.trade_chain_links l where l.chain_id=target_chain_id and target_profile_id in(l.from_profile_id,l.to_profile_id))$$;
drop policy if exists "chain participants read" on public.trade_chains;create policy "chain participants read" on public.trade_chains for select using(public.is_chain_participant(id));
drop policy if exists "chain link participants read" on public.trade_chain_links;create policy "chain link participants read" on public.trade_chain_links for select using(public.is_chain_participant(chain_id));
create policy "chain participants read acceptances" on public.trade_chain_acceptances for select using(public.is_chain_participant(chain_id));
create policy "chain participants read messages" on public.trade_chain_messages for select using(public.is_chain_participant(chain_id));
create policy "chain participants read history" on public.trade_chain_history for select using(public.is_chain_participant(chain_id));
create policy "chain participants read holds" on public.trade_chain_holds for select using(public.is_chain_participant(chain_id));

create or replace function public.validate_trade_chain(target_chain_id uuid)returns void language plpgsql security definer set search_path=public as $$declare link_count int;from_count int;to_count int;walk_count int;begin select count(*),count(distinct from_profile_id),count(distinct to_profile_id)into link_count,from_count,to_count from public.trade_chain_links where chain_id=target_chain_id;if link_count<3 or from_count<>link_count or to_count<>link_count then raise exception 'chain requires at least three unique reciprocal links';end if;if exists(select 1 from public.trade_chain_links a where a.chain_id=target_chain_id and not exists(select 1 from public.trade_chain_links b where b.chain_id=target_chain_id and b.from_profile_id=a.to_profile_id))then raise exception 'every recipient must also provide one link';end if;with recursive walk(profile_id,depth)as((select from_profile_id,1 from public.trade_chain_links where chain_id=target_chain_id order by position limit 1)union all select l.to_profile_id,w.depth+1 from walk w join public.trade_chain_links l on l.chain_id=target_chain_id and l.from_profile_id=w.profile_id where w.depth<link_count)select count(distinct profile_id)into walk_count from walk;if walk_count<>link_count then raise exception 'links must form one closed loop';end if;end$$;

create or replace function public.create_trade_chain(target_circle_id uuid,chain_title text,chain_description text,execution_value text,links jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare new_id uuid;item jsonb;participant uuid;begin if execution_value not in('simultaneous','sequential','conditional')then raise exception 'invalid execution mode';end if;if not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=auth.uid()and status='active')then raise exception 'active circle membership required';end if;for participant in select distinct(value->>'from_profile_id')::uuid from jsonb_array_elements(links)loop if not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=participant and status='active')then raise exception 'every participant must be active in the circle';end if;end loop;insert into public.trade_chains(proposed_by,circle_id,title,description,execution_mode,status)values(auth.uid(),target_circle_id,trim(chain_title),coalesce(chain_description,''),execution_value,'proposed')returning id into new_id;for item in select value from jsonb_array_elements(links)loop insert into public.trade_chain_links(chain_id,from_profile_id,to_profile_id,value_description,position,due_at,conditions)values(new_id,(item->>'from_profile_id')::uuid,(item->>'to_profile_id')::uuid,trim(item->>'value_description'),coalesce((item->>'position')::int,0),nullif(item->>'due_at','')::timestamptz,coalesce(item->>'conditions',''));end loop;perform public.validate_trade_chain(new_id);insert into public.trade_chain_history(chain_id,actor_id,event,note,snapshot)values(new_id,auth.uid(),'proposed','Chain proposed',jsonb_build_object('version',1,'links',links));for participant in select distinct from_profile_id from public.trade_chain_links where chain_id=new_id loop if participant<>auth.uid()then perform public.notify_user(participant,'network','New circle trade chain',trim(chain_title)||' needs your review.');end if;end loop;return new_id;end$$;
create or replace function public.revise_trade_chain(target_chain_id uuid,expected_version integer,payload jsonb)returns void language plpgsql security definer set search_path=public as $$declare c public.trade_chains;item jsonb;participant uuid;begin select * into c from public.trade_chains where id=target_chain_id for update;if not public.is_chain_participant(c.id)or c.version<>expected_version or c.status not in('proposed','accepted')then raise exception 'current editable chain required';end if;delete from public.trade_chain_links where chain_id=c.id;for item in select value from jsonb_array_elements(payload->'links')loop insert into public.trade_chain_links(chain_id,from_profile_id,to_profile_id,value_description,position,due_at,conditions)values(c.id,(item->>'from_profile_id')::uuid,(item->>'to_profile_id')::uuid,trim(item->>'value_description'),coalesce((item->>'position')::int,0),nullif(item->>'due_at','')::timestamptz,coalesce(item->>'conditions',''));end loop;perform public.validate_trade_chain(c.id);update public.trade_chains set title=coalesce(payload->>'title',title),description=coalesce(payload->>'description',description),execution_mode=coalesce(payload->>'execution_mode',execution_mode),version=version+1,status='proposed',updated_at=now()where id=c.id;delete from public.trade_chain_acceptances where chain_id=c.id;insert into public.trade_chain_history(chain_id,actor_id,event,note,snapshot)values(c.id,auth.uid(),'revised','All confirmations reset',payload);end$$;
create or replace function public.accept_trade_chain(target_chain_id uuid,expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare c public.trade_chains;participant_count int;accepted_count int;begin select * into c from public.trade_chains where id=target_chain_id for update;if c.version<>expected_version or c.status<>'proposed'or not public.is_chain_participant(c.id)then raise exception 'current proposed chain required';end if;insert into public.trade_chain_acceptances(chain_id,profile_id,version)values(c.id,auth.uid(),c.version)on conflict(chain_id,profile_id)do update set version=excluded.version,accepted_at=now();select count(distinct from_profile_id)into participant_count from public.trade_chain_links where chain_id=c.id;select count(*)into accepted_count from public.trade_chain_acceptances where chain_id=c.id and version=c.version;if accepted_count=participant_count then update public.trade_chains set status='accepted',updated_at=now()where id=c.id;end if;insert into public.trade_chain_history(chain_id,actor_id,event,note)values(c.id,auth.uid(),'accepted','Participant accepted version '||c.version);end$$;
create or replace function public.activate_trade_chain(target_chain_id uuid)returns void language plpgsql security definer set search_path=public as $$begin update public.trade_chains set status='active',updated_at=now()where id=target_chain_id and status='accepted'and public.is_chain_participant(id);if not found then raise exception 'fully accepted participant chain required';end if;insert into public.trade_chain_history(chain_id,actor_id,event,note)values(target_chain_id,auth.uid(),'activated','All obligations are now active');end$$;
create or replace function public.manage_trade_chain_link(target_link_id uuid,link_action text,note text default null)returns void language plpgsql security definer set search_path=public as $$declare l public.trade_chain_links;c public.trade_chains;begin select * into l from public.trade_chain_links where id=target_link_id for update;select * into c from public.trade_chains where id=l.chain_id for update;if c.status<>'active'then raise exception 'active chain required';end if;if link_action='fulfill'and l.from_profile_id=auth.uid()then if c.execution_mode='sequential'and exists(select 1 from public.trade_chain_links prior where prior.chain_id=c.id and prior.position<l.position and prior.approved_at is null)then raise exception 'earlier links must be approved first';end if;if exists(select 1 from public.trade_chain_holds h where h.chain_id=c.id and(h.link_id is null or h.link_id=l.id)and h.resolved_at is null)then raise exception 'resolve dependency hold first';end if;update public.trade_chain_links set fulfilled_at=now(),evidence_note=nullif(trim(note),'')where id=l.id;elsif link_action='approve'and l.to_profile_id=auth.uid()and l.fulfilled_at is not null then update public.trade_chain_links set approved_at=now()where id=l.id;else raise exception 'link action unavailable';end if;if not exists(select 1 from public.trade_chain_links where chain_id=c.id and approved_at is null)then update public.trade_chains set status='completed',updated_at=now()where id=c.id;end if;insert into public.trade_chain_history(chain_id,actor_id,event,note)values(c.id,auth.uid(),link_action,coalesce(note,''));end$$;
create or replace function public.manage_trade_chain(target_chain_id uuid,chain_action text,payload jsonb default '{}'::jsonb)returns void language plpgsql security definer set search_path=public as $$declare c public.trade_chains;hold_id uuid;begin select * into c from public.trade_chains where id=target_chain_id for update;if not public.is_chain_participant(c.id)then raise exception 'chain participant required';end if;if chain_action='message'then insert into public.trade_chain_messages(chain_id,author_id,body)values(c.id,auth.uid(),trim(payload->>'body'));elsif chain_action='hold'and c.status='active'then insert into public.trade_chain_holds(chain_id,link_id,created_by,kind,detail,action_owner_id,review_at)values(c.id,nullif(payload->>'link_id','')::uuid,auth.uid(),(payload->>'kind')::public.hold_kind,trim(payload->>'detail'),nullif(payload->>'action_owner_id','')::uuid,nullif(payload->>'review_at','')::timestamptz);elsif chain_action='resolve_hold'then update public.trade_chain_holds set resolved_at=now()where id=(payload->>'hold_id')::uuid and chain_id=c.id and resolved_at is null;elsif chain_action in('cancelled','disputed')and c.status not in('completed','cancelled')then update public.trade_chains set status=chain_action,updated_at=now()where id=c.id;else raise exception 'chain action unavailable';end if;insert into public.trade_chain_history(chain_id,actor_id,event,note,snapshot)values(c.id,auth.uid(),chain_action,coalesce(payload->>'detail',payload->>'body',''),payload);end$$;

create or replace function public.get_trade_chain_hub(target_circle_id uuid)returns jsonb language sql stable security definer set search_path=public as $$select case when not exists(select 1 from public.circle_members where circle_id=target_circle_id and profile_id=auth.uid()and status='active')then jsonb_build_object('chains','[]'::jsonb,'suggestions','[]'::jsonb)else jsonb_build_object('chains',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('links',(select jsonb_agg(to_jsonb(l)||jsonb_build_object('from_name',fp.display_name,'to_name',tp.display_name)order by l.position)from public.trade_chain_links l join public.profiles fp on fp.id=l.from_profile_id join public.profiles tp on tp.id=l.to_profile_id where l.chain_id=c.id),'acceptances',(select coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb)from public.trade_chain_acceptances a where a.chain_id=c.id),'messages',(select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('author_name',p.display_name)order by m.created_at),'[]'::jsonb)from public.trade_chain_messages m join public.profiles p on p.id=m.author_id where m.chain_id=c.id),'history',(select coalesce(jsonb_agg(to_jsonb(h)order by h.created_at desc),'[]'::jsonb)from public.trade_chain_history h where h.chain_id=c.id),'holds',(select coalesce(jsonb_agg(to_jsonb(d)),'[]'::jsonb)from public.trade_chain_holds d where d.chain_id=c.id))order by c.updated_at desc)from public.trade_chains c where c.circle_id=target_circle_id and public.is_chain_participant(c.id)),'[]'::jsonb),'suggestions',coalesce((select jsonb_agg(suggestion)from(select distinct jsonb_build_object('participants',jsonb_build_array(a.profile_id,b.profile_id,c.profile_id),'links',jsonb_build_array(jsonb_build_object('from_profile_id',a.profile_id,'to_profile_id',b.profile_id,'value_description',a.label),jsonb_build_object('from_profile_id',b.profile_id,'to_profile_id',c.profile_id,'value_description',b.label),jsonb_build_object('from_profile_id',c.profile_id,'to_profile_id',a.profile_id,'value_description',c.label)),'explanation',pa.display_name||' offers '||a.label||' to '||pb.display_name||'; '||pb.display_name||' offers '||b.label||' to '||pc.display_name||'; '||pc.display_name||' offers '||c.label||' to '||pa.display_name) suggestion from public.capabilities a join public.capabilities bn on bn.direction='need'and lower(bn.label)=lower(a.label)and bn.profile_id<>a.profile_id join public.capabilities b on b.profile_id=bn.profile_id and b.direction='offer'join public.capabilities cn on cn.direction='need'and lower(cn.label)=lower(b.label)and cn.profile_id not in(a.profile_id,b.profile_id)join public.capabilities c on c.profile_id=cn.profile_id and c.direction='offer'join public.capabilities an on an.profile_id=a.profile_id and an.direction='need'and lower(an.label)=lower(c.label)join public.profiles pa on pa.id=a.profile_id join public.profiles pb on pb.id=b.profile_id join public.profiles pc on pc.id=c.profile_id where a.direction='offer'and exists(select 1 from public.circle_members m where m.circle_id=target_circle_id and m.status='active'and m.profile_id=a.profile_id)and exists(select 1 from public.circle_members m where m.circle_id=target_circle_id and m.status='active'and m.profile_id=b.profile_id)and exists(select 1 from public.circle_members m where m.circle_id=target_circle_id and m.status='active'and m.profile_id=c.profile_id)limit 10)s),'[]'::jsonb))end$$;
revoke all on function public.validate_trade_chain(uuid),public.create_trade_chain(uuid,text,text,text,jsonb),public.revise_trade_chain(uuid,integer,jsonb),public.accept_trade_chain(uuid,integer),public.activate_trade_chain(uuid),public.manage_trade_chain_link(uuid,text,text),public.manage_trade_chain(uuid,text,jsonb),public.get_trade_chain_hub(uuid)from public;
grant execute on function public.create_trade_chain(uuid,text,text,text,jsonb),public.revise_trade_chain(uuid,integer,jsonb),public.accept_trade_chain(uuid,integer),public.activate_trade_chain(uuid),public.manage_trade_chain_link(uuid,text,text),public.manage_trade_chain(uuid,text,jsonb),public.get_trade_chain_hub(uuid)to authenticated;
